package com.example.demo.aspect; import org.aspectj.lang.JoinPoint; import org.aspectj.lang.annotation.*; import org.springframework.stereotype.Component; @Aspect @Component public class LoggingAspect { @Before("execution(* com.example.demo.service.*.*(..))") public void logBeforeMethodCall(JoinPoint jp){System.out.println("[AOP-BEFORE] Intercepting execution route! Triggering before: "+jp.getSignature().getName());} }